/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_products_after_insert` AFTER INSERT ON `tb_products` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (table_name, table_operation, db_user, operation_description)
    VALUES ('tb_products','Create', USER(),
        CONCAT('Producto creado: "', NEW.name, '". SKU: ', NEW.SKU,
               ', Precio: $', NEW.current_price, ', Stock inicial: ', NEW.current_stock));
END */;;
