    IF NOT (OLD.current_price <=> NEW.current_price) THEN
        SET changes_detail = CONCAT(changes_detail, 'Precio: $', OLD.current_price, ' -> $', NEW.current_price, '; ');
    END IF;
    IF NOT (OLD.current_stock <=> NEW.current_stock) THEN
        SET changes_detail = CONCAT(changes_detail, 'Stock: ', OLD.current_stock, ' -> ', NEW.current_stock, '; ');
    END IF;
    IF NOT (OLD.status <=> NEW.status) THEN
        SET changes_detail = CONCAT(changes_detail, 'Estado: ', CAST(OLD.status AS UNSIGNED), ' -> ', CAST(NEW.status AS UNSIGNED), '; ');
    END IF;
    IF CHAR_LENGTH(changes_detail) > 0 THEN
        INSERT INTO tb_logs (table_name, table_operation, db_user, operation_description)
        VALUES ('tb_products','Update', USER(), TRIM(changes_detail));
    END IF;
END */;;
