/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_restore_product`(IN p_product_id INT UNSIGNED)
BEGIN
    IF NOT EXISTS (SELECT 1 FROM tb_products WHERE ID = p_product_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El producto especificado no existe';
    END IF;
    IF EXISTS (SELECT 1 FROM tb_products WHERE ID = p_product_id AND status = b'1') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El producto ya se encuentra activo';
    END IF;
    UPDATE tb_products SET status = b'1' WHERE ID = p_product_id;
END ;;
DELIMITER ;
